// Target: 0x003881B0 nvlMPEGAdvance__Fv
// Reference: NVL/PS2/nvlMPEG_ps2.cpp
#define READ_UNIT_SIZE (64 * 1024)
#define NVLMPEG_PRIORITY 1
#define VD_STATE_END 3
#define true 1
#define false 0

struct sceMpeg {};
struct VideoDec {
    sceMpeg mpeg;
};
struct StrFile {};
struct ReadBuf {
    unsigned char data[5 * READ_UNIT_SIZE];
    int put;
    int count;
    int size;
};
struct AudioDec {};
struct VoBuf {};

extern int writerest;
extern int readrest;
extern int isStarted;
extern VideoDec videoDec;
extern StrFile infile;
extern ReadBuf *readBuf;
extern AudioDec audioDec;
extern VoBuf voBuf;

extern unsigned int videoDecGetState(VideoDec *);
extern int readBufBeginPut(ReadBuf *, unsigned char **);
extern int strFileRead(StrFile *, void *, int);
extern int readBufEndPut(ReadBuf *, int);
extern int RotateThreadReadyQueue(int);
extern int readBufBeginGet(ReadBuf *, unsigned char **);
extern int sceMpegDemuxPssRing(sceMpeg *, void *, int, void *, int);
extern int readBufEndGet(ReadBuf *, int);
extern int audioDecSendToIOP(AudioDec *);
extern int voBufIsFull(VoBuf *);
extern int audioDecIsPreset(AudioDec *);
extern void startDisplay(int);
extern void audioDecStart(AudioDec *);

int nvlMPEGAdvance()
{
    unsigned char   *put_ptr, *get_ptr;
    int putsize, getsize, count, proceed;

    // writerest > 4: to skip the last 4 bytes
    if( writerest > 4 && videoDecGetState(&videoDec) != VD_STATE_END )
    {
        putsize = readBufBeginPut( readBuf, &put_ptr );
        if( readrest > 0 && putsize >= READ_UNIT_SIZE )
        {
            count = strFileRead( &infile, put_ptr, READ_UNIT_SIZE );
            readBufEndPut( readBuf, count );
            readrest -= count;
        }

        RotateThreadReadyQueue( NVLMPEG_PRIORITY );

        getsize = readBufBeginGet( readBuf, &get_ptr );
        if( getsize > 0 )
        {
            proceed = sceMpegDemuxPssRing( &videoDec.mpeg, get_ptr, getsize, readBuf->data, readBuf->size );
            readBufEndGet( readBuf, proceed );
            writerest -= proceed;
        }

        audioDecSendToIOP( &audioDec );

        if( !isStarted && voBufIsFull(&voBuf) && audioDecIsPreset(&audioDec) )
        {
            startDisplay( 1 );
            audioDecStart( &audioDec );
            isStarted = 1;
        }
        return true;
    }
    return false;
}
